/**
 * Text-to-speech read-outs.
 *
 *   GET  /api/tts/config   what the browser needs to decide whether to show the read-out icon
 *   POST /api/tts          { text, lang, voice? } -> { url, cached, chars }
 *
 * Audio is generated by a Replicate model (TTS_REPLICATE_MODEL), stored once through the normal
 * storage layer (local disk or S3/R2) and reused for identical text, so each passage is paid for
 * once. The Replicate token never leaves the server.
 */
const crypto = require('crypto');
const ttsConfig = require('./config');
const { normLang } = require('./languages');
const { synthesize } = require('./replicate');
const data = require('./data');
const { isAdmin } = require('../../lib/auth');
const { DOCUMENTED } = require('./languages');

module.exports = function routes(route, kit) {
  const { roomParticipant, getAuthUser, httpError, rateLimit, storage } = kit;
  const cfg = ttsConfig.load();
  const inflight = new Map(); // hash -> promise, so two people asking at once pay once
  const budget = { day: '', chars: 0 };
  const undocumented = cfg.languages.filter((l) => !DOCUMENTED.some(([c]) => c === l));
  if (cfg.token && undocumented.length) console.warn(`[tts] TTS_LANGUAGES has codes not on Google’s Gemini TTS list: ${undocumented.join(', ')} (they will be sent anyway)`);

  // The model treats <tags>, |backchannels| and /IPA/ as directions, so user text is neutralised:
  // content is read verbatim, never "performed".
  const clean = (t) => String(t || '')
    .replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, ' ')
    .replace(/[<>|]/g, ' ')
    .replace(/\//g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  route('GET', '/api/tts/config', async () => ({
    enabled: !!cfg.token,
    provider: 'replicate',
    model: cfg.model.split(':')[0],
    languages: cfg.languages,
    maxChars: cfg.maxChars,
    voices: ttsConfig.VOICES,
    defaultVoice: cfg.voice,
  }));

  route('POST', '/api/tts', async ({ req, res, body }) => {
    if (!cfg.token) throw httpError(503, 'Read-out is not set up on this server');
    const b = await body(64 * 1024);
    const rp = roomParticipant(req, b.code);
    const user = rp ? null : await getAuthUser(req, res);
    if (!rp && !user) throw httpError(401, 'Sign in to listen');

    const lang = normLang(b.lang);
    if (!lang || !cfg.languages.includes(lang)) throw httpError(400, 'Read-out is not available for this language');
    const text = clean(b.text);
    if (!text) throw httpError(400, 'Nothing to read');
    if (text.length > cfg.maxChars) throw httpError(413, `Too long to read at once (max ${cfg.maxChars} characters)`);
    const voice = ttsConfig.VOICES.includes(b.voice) ? b.voice : cfg.voice;

    const hash = crypto.createHash('sha256').update([cfg.model, voice, cfg.format, lang, text].join('\u0001')).digest('hex');
    const hit = await data.getCached(hash);
    if (hit) return { url: storage().publicUrl(hit), cached: true, chars: text.length };

    // Only new audio costs money, so only new audio counts against the limits.
    const who = rp ? `p:${rp.code}:${rp.participant.id}` : `u:${user.id}`;
    if (!rateLimit('tts:' + who, cfg.ratePerMin)) throw httpError(429, 'You are listening a lot — wait a minute and try again');
    const today = new Date().toISOString().slice(0, 10);
    if (budget.day !== today) { budget.day = today; budget.chars = 0; }
    if (cfg.dailyChars && budget.chars + text.length > cfg.dailyChars) throw httpError(429, 'Read-out has reached today’s limit on this server');

    if (!inflight.has(hash)) {
      budget.chars += text.length;
      inflight.set(hash, (async () => {
        const { audio, mime } = await synthesize(cfg, { text, voice, output_format: cfg.format });
        const rec = await storage().save(audio, { filename: `tts-${hash.slice(0, 16)}.${mime === 'audio/wav' ? 'wav' : 'mp3'}`, mime, purpose: 'tts' });
        await data.putCached({ hash, fileId: rec.id, lang, voice, model: cfg.model, chars: text.length });
        return rec.url;
      })().catch((e) => { budget.chars = Math.max(0, budget.chars - text.length); throw e; })
        .finally(() => inflight.delete(hash)));
    }
    try {
      return { url: await inflight.get(hash), cached: false, chars: text.length };
    } catch (e) {
      // Admins see the provider's reason (bad token, billing, model error) to fix setup quickly.
      if (user && isAdmin(user) && e.detail) throw httpError(e.status || 502, `${e.message} — ${e.detail}`);
      throw e;
    }
  });
};
